  c1 = signal<boolean>(true);
  c2 = signal<boolean>(true);
  c3 = signal<boolean>(false);
  c4 = signal<boolean>(false);

  lockedA = signal<boolean>(true);
  lockedB = signal<boolean>(false);

  viewedFlag = signal<boolean>(true);
